insert into fish_species (name, slug, latin, description, season, methods, sort_order) values
  ('Судак', 'sudak', 'Sander lucioperca', 'Один из главных хищников водохранилищ и крупных рек Казахстана: обычен на Капшагае, Балхаше, Бухтарминском и Шардаринском водохранилищах, в бассейнах Урала, Иртыша и Сырдарьи. Ценится за упорное сопротивление и вкусное белое мясо, считается трофеем номер один у спиннингистов.', 'Лучший клёв — весной (апрель–май) до нереста и осенью (сентябрь–ноябрь); зимой хорошо ловится со льда на жерлицы и балансиры.', 'Спиннинг с джигом (силикон, поролон), ловля на живца, троллинг, зимой — отвесное блеснение и жерлицы.', 10),
  ('Щука', 'shchuka', 'Esox lucius', 'Широко распространена почти по всему Казахстану — в дельте Или, на Балхаше, Зайсане, Бухтарме, в пойменных озёрах Иртыша и Урала. Засадный хищник, интересен агрессивными поклёвками и крупными размерами (до 8–10 кг и больше).', 'Пик — по открытой воде весной сразу после схода льда (март–апрель) и осенний жор (сентябрь–ноябрь); активна и зимой со льда.', 'Спиннинг (колебалки, воблеры, джиг), ловля на живца и кружки, зимой — жерлицы и блеснение.', 20),
  ('Окунь', 'okun', 'Perca fluviatilis', 'Массовый и повсеместный хищник: населяет практически все реки, озёра и водохранилища страны от Балхаша до Иртыша. Отлично подходит для начинающих и семейной рыбалки, ловится стабильно круглый год, крупные горбачи достигают 1 кг и более.', 'Клюёт весь сезон; наиболее активен осенью и по перволёдью, а также весной по мутной воде.', 'Поплавочная удочка, лёгкий спиннинг (микроджиг, вертушки), отводной поводок, зимой — мормышка и мелкие блёсны.', 30),
  ('Сазан (карп)', 'sazan-karp', 'Cyprinus carpio', 'Дикий сазан и его одомашненная форма карп — одни из самых желанных мирных рыб Казахстана: обитают на Балхаше, Капшагае, Шардаре, в низовьях Сырдарьи, Или и Урала. Сильный, осторожный боец, трофейные экземпляры превышают 10–15 кг.', 'Активен в тёплой воде с мая по сентябрь, пик — в июне и в конце лета; зимой практически не питается.', 'Донные снасти (фидер, макушатник), карповая ловля с бойлами, поплавочная удочка на кукурузу, горох и тесто.', 40),
  ('Карась', 'karas', 'Carassius gibelio', 'Неприхотливая рыба, населяющая множество озёр, прудов, стариц и водохранилищ по всему Казахстану; серебряный карась особенно многочислен. Идеальный объект для доступной и спокойной рыбалки, хорошо переносит заморные водоёмы.', 'Ловится с апреля по октябрь, лучший клёв — в тёплые дни поздней весны и летом на утренней и вечерней зорях.', 'Поплавочная удочка и лёгкий фидер на червя, опарыша, тесто, манку и кукурузу.', 50),
  ('Лещ', 'leshch', 'Abramis brama', 'Стайная донная рыба, обычная в бассейнах Урала, Иртыша, Сырдарьи, а также на Бухтарминском и Капшагайском водохранилищах и озере Зайсан. Ценится за вкусное мясо и вяление, привлекает любителей ловли крупной мирной рыбы.', 'Лучший клёв — с конца весны (после нереста в мае) до осени; неплохо ловится и со льда зимой.', 'Фидер и донные снасти, поплавочная удочка на червя, опарыша, перловку и тесто; прикормка обязательна.', 60),
  ('Жерех', 'zhereh', 'Aspius aspius', 'Стремительный поверхностный хищник рек Урал, Иртыш, Сырдарья и Или, встречается и в крупных водохранилищах. Знаменит эффектным боем малька на поверхности («жереховый бой») и мощным сопротивлением, достигает 8–10 кг.', 'Пик активности — с мая по сентябрь в тёплой воде, особенно в жаркие летние дни на перекатах.', 'Спиннинг дальнего заброса (кастмастеры, пилькеры, вертушки), ловля на живца, нахлыст по бою.', 70),
  ('Сом', 'som', 'Silurus glanis', 'Крупнейший пресноводный хищник Казахстана, обитает в Урале, Сырдарье, Или, на Капшагае, Балхаше и Шардаринском водохранилище. Ночной донный хищник, трофейные особи превышают 50–100 кг — главный трофей для любителей ловли гигантов.', 'Активен в тёплое время года (июнь–сентябрь), особенно в тёплые ночи; зимой залегает в ямы и не питается.', 'Донные снасти и квок на живца, лягушку, ракушку и пучок червей; крупный джиг и глубоководные воблеры на спиннинг.', 80),
  ('Налим', 'nalim', 'Lota lota', 'Единственный пресноводный представитель тресковых, любит холодную чистую воду бассейна Иртыша — Чёрный Иртыш, Курчум, Нарым, Бухтарма, озеро Зайсан. Уникален тем, что наиболее активен зимой, когда другая рыба пассивна.', 'Клюёт по холодной воде: поздней осенью и особенно зимой в период нереста (декабрь–февраль); летом малоактивен.', 'Донки и закидушки на живца и куски рыбы ночью, зимой — стукалка и отвесное блеснение со льда.', 90),
  ('Плотва (вобла)', 'plotva-vobla', 'Rutilus rutilus caspicus', 'Массовая стайная рыба; каспийская полупроходная форма — вобла — заходит на нерест в реку Урал, а обыкновенная плотва населяет большинство озёр и водохранилищ страны. Популярный объект весенней и вяленой рыбалки, доступный каждому.', 'Отличный клёв весной в преднерестовый ход (март–апрель) и осенью; зимой стабильно ловится со льда.', 'Поплавочная удочка и лёгкий фидер на опарыша, червя, тесто; зимой — мормышка с мотылём.', 100),
  ('Толстолобик', 'tolstolobik', 'Hypophthalmichthys molitrix', 'Крупный планктоноядный вселенец, акклиматизированный в Или, Сырдарье, на Капшагае, Шардаре и в прудовых хозяйствах для очистки водоёмов. Интересен внушительными размерами (до 20–30 кг) и мощной борьбой, но клюёт своеобразно из-за питания фитопланктоном.', 'Ловится в жаркий период с июня по сентябрь, когда активно кормится в верхних слоях воды.', 'Специальная снасть «убийца толстолобика» с технопланктоном, донные оснастки; изредка попадается на поплавок.', 110),
  ('Белый амур', 'belyy-amur', 'Ctenopharyngodon idella', 'Растительноядный вселенец с Дальнего Востока, разведённый в водоёмах Или, Сырдарьи, на Капшагае, Шардаре и в рыбхозах для борьбы с зарастанием. Сильная и осторожная рыба, трофеи достигают 15–20 кг, ценится за спортивную ловлю и вкусное мясо.', 'Активен в тёплой воде с конца мая по сентябрь, особенно в жару у зарослей водной растительности.', 'Поплавочная и донная снасти на растительные насадки — молодой камыш, водоросли, огурец, кукурузу, а также бойлы.', 120),
  ('Форель', 'forel', 'Oncorhynchus mykiss / Salmo trutta', 'Обитает в холодных горных реках и озёрах юго-востока и востока Казахстана (бассейны Или, Тянь-Шаня, Алтая), а радужная форель широко разводится в платных прудах и садках. Красивая, бойкая рыба — желанный трофей нахлыстовиков и любителей ходовой рыбалки.
